import *as THREE from'three';
import{Port,materials}from'../../core/index.js';
import{mesh,FACE,portQuaternion}from'../../modeling/parts.js';
import{spec}from'./dimensions.js';
export function grove(host){
 const frame=new THREE.Group();frame.name='HBridge v1.1 burgundy open-top HY2.0-4P';frame.position.fromArray(spec.grove.position);frame.quaternion.copy(FACE.bottom);host.body.add(frame);const plastic=materials.plastic(spec.grove.color,{roughness:.65}),metal=materials.metal(0xb9ad82,{roughness:.44}),box=(size,p,name,mat=plastic)=>mesh(frame,new THREE.BoxGeometry(...size),mat,p,'HBridge v1.1 Grove '+name);
 for(const x of[-4.65,4.65]){box([.7,5.2,6.5],[x,0,-3.25],'side wall');box([.85,.75,3.1],[Math.sign(x)*3.85,2.2,-4.8],'guide rail');box([.7,.9,.6],[x,2.05,0],'mouth ear');}box([8.6,.7,6.5],[0,-2.25,-3.25],'floor');box([8.6,5.2,.6],[0,0,-6.2],'recessed rear wall');box([8.6,2.65,3.6],[0,-1.25,-4.7],'recessed contact carrier');box([3.4,.65,2.7],[0,1.2,-5.1],'short locking tongue');const contacts=[];for(let i=0;i<4;i++){contacts.push(box([.42,.42,4],[(i-1.5)*2,-.15,-3.2],`contact ${i+1}`,metal));box([.42,1.2,.42],[(i-1.5)*2,-1.4,-5.7],`PCB tail ${i+1}`,metal);}
 const port=host.add(new Port({id:'grove',label:'PORT.A · I2C',connector:'grove',position:spec.grove.position,quaternion:portQuaternion('bottom'),hitSize:[10,1,5.2],pins:[{n:1,name:'GND',color:'black'},{n:2,name:'5V',color:'red'},{n:3,name:'SDA',color:'yellow'},{n:4,name:'SCL',color:'white'}],pinGrid:{cols:4,rows:1,pitch:2,center:[0,-.15],order:col=>4-col},meta:{role:'visual-connector',face:'bottom',protocol:'I2C',i2cAddress:'0x20',scope:'Physical four-core connector and cable pose only; no I2C, conversion, current, calibration, fuse or isolation behavior'}}));return{frame,contacts,port};
}
export function terminal(host){
 const frame=new THREE.Group();frame.name='HBridge v1.1 fixed orange HT3.96-4P measurement socket';frame.position.fromArray(spec.terminal.position);host.body.add(frame);const orange=materials.plastic(0xf5933a,{roughness:.66}),metal=materials.metal(0xb7b8a6,{roughness:.45}),parts=[],box=(sz,p,n,mat=orange)=>{const m=mesh(frame,new THREE.BoxGeometry(...sz),mat,p,'HBridge v1.1 fixed terminal '+n);parts.push(m);return m;};
 const rear=box([16,.7,7],[0,-9.65,0],'rear support');for(const side of[-1,1])box([.65,9.3,7],[side*7.675,-4.65,0],'side cheek');box([14.7,9.3,.55],[0,-4.65,-3.225],'lower retention floor');box([14.7,6.95,.55],[0,-3.475,3.225],'upper forward retention wall');box([14.7,.85,.55],[0,-8.875,3.225],'upper rear retention wall');for(const x of[-7.5,-3.96,0,3.96,7.5])box([.65,1.5,.55],[x,-7.7,3.225],'upper real slot partition');box([16,.5,.55],[0,-8.45,3.225],'upper slot rear rib');
 const contacts=[];for(const x of spec.terminal.pinX){contacts.push(box([.62,7.2,.62],[x,-4.6,-.4],'recessed contact pin',metal));box([.62,.62,1.6],[x,-9.65,-1.2],'PCB tail',metal);}
 const port=host.add(new Port({id:'terminal',label:'HV / G / motor · HT3.96-4P',connector:'ht3.96-4p',position:spec.terminal.position,hitSize:[16,1,7],pins:spec.terminal.names.map((name,i)=>({n:i+1,name})),pinGrid:{cols:4,rows:1,pitch:3.96,center:[0,-.4],order:col=>col+1},meta:{role:'visual-connector',face:'top',terminalOrderEvidence:'Own U160-V11 front print left-to-right HV,G,M−,M+; n is spatial slot index and reverses schematic P5 pin1…4. No electrical continuity model.',scope:'Physical motor/power socket and detachable plug only; no wiring, polarity, continuity, current, voltage, switching, PWM, motor or electrical behavior'}}));return{frame,rear,parts,contacts,port};
}
